    'MixTally is an open construction technology platform providing formula-based material quantity estimation paired with real-time interactive 3D spatial visualization.',
  'about.imageAlt': 'Site worker writing notes on a clipboard over construction drawings',
  'about.problemTitle': 'The Problem We Solve',
  'about.problemBody1':
    'Traditional building material calculators present users with flat numerical web forms. When entering multi-unit dimensions—such as a concrete slab measured in feet for length and width, but inches for thickness—clerical mistakes happen frequently. A misplaced decimal point or confused unit yields an answer off by a factor of 12.',
  'about.problemBody2':
    'In physical construction, ordering mistakes cause immediate project disruptions: under-ordering concrete leads to emergency short-load delivery fees or weak cold joints, while over-ordering results in wasted budget and difficult slurry disposal.',
  'about.why3dTitle': 'Why Interactive 3D Spatial Modeling Matters',
  'about.why3dBody':
    'By coupling numerical input fields directly to a parametric WebGL 3D model, MixTally provides immediate visual feedback. If a user accidentally enters a 4-inch slab as 4.0 feet, the slab physically morphs into a monolithic cube in the viewport, catching the input error before any material orders are placed.',
