      'Los volúmenes se traducen de inmediato en unidades comerciales reales: cargas de hormigonera, sacos de mezcla o cubetas comerciales.',
    'home.faqEyebrow': 'Base de conocimiento de campo',
    'home.faqTitle': 'Principios prácticos de cálculo de obra',
    'home.faqBody':
      'Preguntas frecuentes sobre el desnivel del terreno, factores de merma, márgenes de mortero y deducción de aberturas.',
    'home.faq1Question': '¿Por qué hay que añadir un margen de pedido a las losas de concreto?',
    'home.faq1Answer':
      'Los terrenos excavados rara vez quedan perfectamente nivelados. Pequeños desniveles de apenas 1/2 pulgada en un patio de 20×20 ft aumentan el consumo de concreto en casi 0,6 yardas cúbicas. La cimbra de madera también se deforma ligeramente hacia afuera bajo la presión hidrostática del concreto fresco. Añadir un margen de pedido del 5% al 10% evita las uniones en frío provocadas por emergencias de vertido insuficiente.',
    'home.faq2Question': '¿Cuántos ladrillos modulares se necesitan por pie cuadrado de pared?',
    'home.faq2Answer':
      'Los ladrillos aparentes modulares estándar (7-5/8" × 2-1/4" × 3-5/8") con lecho y junta de cabeza estándar de 3/8" producen un aparejo efectivo de 8" × 2-2/3". Esto equivale matemáticamente a aproximadamente 6,75 a 7,0 ladrillos por pie cuadrado de pared de hilada simple.',
    'home.faq3Question': '¿Cuándo se deben deducir las aberturas en la estimación de pintura?',
    'home.faq3Answer':
      'Las puertas interiores estándar suelen medir ~21 ft² (2,0 m²) y las ventanas residenciales estándar ocupan ~15 ft² (1,4 m²). Deducir las aberturas importantes evita compras excesivas de pintura en proyectos de varias habitaciones.',
    'home.faq4Question':
      '¿Cómo se comparan el rendimiento de los sacos con los camiones de hormigón fresco entregados?',
    'home.faq4Answer':
      'Una yarda cúbica contiene 27 pies cúbicos. Un saco estándar de mezcla de concreto de 80 lb rinde aproximadamente 0,60 pies cúbicos, lo que significa que se requieren 45 sacos de concreto de 80 lb (o 60 sacos de 60 lb) para fabricar una yarda cúbica. Para vertidos superiores a 2 yardas cúbicas, los camiones de hormigón fresco entregado suelen ser más económicos.',

