    'brick.copy.mortar': 'Mortero tipo N (sacos de 80 lb): {bags} sacos (~{cuft} ft³)',
    'brick.copy.cost': 'Costo estimado del material de cantería: ${cost} (@ ${price}/ladrillo)',
    'brick.faqQ1': '¿Cuántos ladrillos necesito para una pared?',
    'brick.faqA1':
      'Introduzca el largo y el alto de la pared, elija un preajuste de ladrillo (que define el tamaño del ladrillo y el espesor de la junta de mortero) y luego seleccione el número de hiladas y el margen de merma. La calculadora multiplica el área frontal de la pared por el área efectiva del ladrillo por unidad para obtener la cantidad base y añade el margen de merma para la estimación de planificación.',
    'brick.faqQ2': '¿Cuántos ladrillos se necesitan por pie cuadrado?',
    'brick.faqA2':
      'Con el ladrillo modular estándar (7 5/8 in por 2 1/4 in) colocado en una junta de mortero de 3/8 in, la calculadora usa aproximadamente 6,86 ladrillos por pie cuadrado de pared de hilada simple. En unidades métricas, el valor predeterminado es un ladrillo de 194 mm por 57 mm con una junta de 10 mm.',
    'brick.faqQ3': '¿Cómo calculo los ladrillos de una pared?',
    'brick.faqA3':
      'Calcule el área frontal de la pared, determine el área frontal efectiva del ladrillo incluyendo la junta de mortero, divida el área de la pared por el área efectiva del ladrillo para obtener la cantidad base, multiplique por el número de hiladas y añada un margen de merma.',
    'brick.faqQ4': '¿Cuánto mortero necesito para la cantería?',
    'brick.faqA4':
      'La calculadora usa un supuesto de planificación de aproximadamente 130 ladrillos modulares por saco de 80 lb de mortero tipo N e informa la cantidad de sacos además del volumen aproximado de mezcla seca. La necesidad real de mortero varía según las dimensiones del ladrillo, el espesor de la junta, la construcción de la pared, la mano de obra y el rendimiento del producto.',
    'brick.faqQ5': '¿Cuánta merma debo añadir al pedir ladrillos?',
    'brick.faqA5':
      'La merma depende del tamaño de la pared, el patrón de aparejo, los cortes y las roturas. La calculadora ofrece preajustes del 5%, 8%, 10% y 15% para que elija el margen que mejor se adapte a su proyecto, y muestra los ladrillos de merma que añade a la cantidad base.',
    'brick.faqQ6': '¿Cuál es la diferencia entre paredes de hilada simple y hilada doble?',
    'brick.faqA6':
      'Una hilada simple es una capa (hoja) de ladrillo, mientras que una hilada doble son dos capas. La calculadora multiplica la cantidad base de ladrillos por el número de hiladas seleccionado, de modo que una pared de hilada doble con la misma área frontal necesita aproximadamente el doble de ladrillos.',
    'brick.faqQ7': '¿Qué tamaños de ladrillo admite esta calculadora?',
    'brick.faqA7':
      'Tres preajustes de ladrillo: Modular, Queen y King. Cada preajuste carga un largo y un alto de ladrillo correspondientes y el espesor predeterminado de la junta de mortero, y el botón muestra las dimensiones que utiliza. El largo y el alto de la pared se introducen directamente, en unidades métricas o imperiales.',
    'brick.faqQ8': '¿Puedo calcular los ladrillos con medidas en el sistema métrico?',
    'brick.faqA8':
      'Sí. Cambie el control de unidades a Métrico (m / mm) para introducir el largo y el alto en metros. Los preajustes de ladrillo y la junta de mortero pasan a usar dimensiones en milímetros, como un ladrillo modular de 194 mm por 57 mm con una junta de 10 mm, y el área de la pared se informa en metros cuadrados.',
