    'home.workflowEyebrow1': 'Fluxo de engenharia',
    'home.workflowEyebrow2': 'Pipeline de cálculo transparente',
    'home.workflowTitle': 'Veja o cálculo, não apenas o número.',
    'home.workflowBody':
      'A MixTally conecta as dimensões físicas da obra diretamente à geometria paramétrica 3D e a fórmulas matemáticas verificadas para fornecer estimativas de planejamento claras.',
    'home.step1Label': '01. DIMENSÕES',
    'home.step1Title': 'Medidas de campo',
    'home.step1Body':
      'Informe medidas reais em unidades imperiais ou métricas. Valores decimais arbitrários são aceitos, com validação de limites instantânea.',
    'home.step2Label': '02. MODELO ESPACIAL 3D',
    'home.step2Title': 'Visualização paramétrica',
    'home.step2Body':
      'As coordenadas da malha escalam dinamicamente nos eixos X, Y e Z. As chamadas de dimensão verificam visualmente as proporções.',
    'home.step3Label': '03. MOTOR DE FÓRMULAS',
    'home.step3Title': 'Matemática de volume e desperdício',
    'home.step3Body':
      'Equações geométricas padrão combinadas com margens de ofício configuráveis para desníveis do subleito e perdas de corte.',
    'home.step4Label': '04. MEDIÇÃO DO PEDIDO',
    'home.step4Title': 'Unidades de compra',
    'home.step4Body':
      'Os volumes se traduzem imediatamente em unidades comerciais reais: cargas de betoneira, sacos de concreto pronto ou latas comerciais.',

    'home.faqEyebrow': 'Base de conhecimento de campo',
    'home.faqTitle': 'Princípios práticos de medição de obras',
    'home.faqBody':
      'Perguntas frequentes sobre desníveis do subleito, fatores de desperdício, margens de argamassa e deduções de aberturas.',
    'home.faq1Question': 'Por que é preciso acrescentar uma margem de pedido nas lajes de concreto?',
    'home.faq1Answer':
      'Subleitos escavados raramente ficam perfeitamente nivelados. Pequenos buracos e depressões de até 1/2 polegada num pátio de 20×20 ft aumentam o consumo de concreto em quase 0,6 jardineira cúbica. A fôrma de madeira também cede levemente para fora sob a pressão hidrostática do concreto fresco. Acrescentar de 5% a 10% de margem de pedido evita junta fria causada por emergências de concreto insuficiente.',
    'home.faq2Question': 'Quantos tijolos modulares são necessários por metro quadrado de parede?',
    'home.faq2Answer':
      'Tijolos aparentes modulares padrão (7-5/8" × 2-1/4" × 3-5/8") com junta de leito e cabeça padrão de 3/8" resultam em uma face efetiva de assentamento de 8" × 2-2/3". Matematicamente, isso equivale a aproximadamente 6,75 a 7,0 tijolos por metro quadrado de parede de uma fiada.',
    'home.faq3Question': 'Quando devem ser deduzidas as aberturas na estimativa de tinta?',
    'home.faq3Answer':
      'Portas internas padrão medem tipicamente ~21 sq ft (2,0 m²) e janelas residenciais padrão ocupam ~15 sq ft (1,4 m²). Deduzir as principais aberturas evita compras excessivas de tinta em projetos com vários ambientes.',
    'home.faq4Question': 'Como o rendimento dos sacos se compara às betoneiras entregues?',
    'home.faq4Answer':
      'Uma jardineira cúbica contém 27 pés cúbicos. Um saco padrão de concreto pronto de 80 lb rende aproximadamente 0,60 pé cúbico, ou seja, são necessários 45 sacos de 80 lb (ou 60 sacos de 60 lb) para fazer uma jardineira cúbica. Para concretagens acima de 2 jardineiras cúbicas, as betoneiras entregues costumam sair mais econômicas.',

