    'guides.eyebrow': 'Referência e guias de construção',
    'guides.title': 'Guias de campo e princípios de medição de materiais',
    'guides.body':
      'Guias técnicos aprofundados que explicam fórmulas de cálculo volumétrico, fatores de desperdício nominais, geometria de assentamento e práticas comerciais de pedido.',
    'guides.launchCalculator': 'Abrir calculadora',
    'guides.concreteBadge': 'Guia de concreto 01',
    'guides.concreteTitle': 'Como calcular o volume da laje de concreto e os pedidos de concreto usinado',
    'guides.concreteIntro':
      'O concreto concretado é medido e comprado em <strong>jardineiras cúbicas</strong> (no sistema de medidas dos EUA) ou em <strong>metros cúbicos</strong> (em países de sistema métrico). Como as dimensões de obra costumam ser anotadas em pés para comprimento e largura, mas em polegadas para a espessura da laje, a conversão correta de unidades é essencial:',
    'guides.concreteSubhead': 'Por que o desnível do subleito exige uma margem de pedido',
    'guides.concreteBody':
      'A escavação do terreno raramente fica perfeitamente plana. O subleito afunda, as fôrmas cedem para fora sob a pressão hidrostática do concreto fresco e as linhas de bomba retêm argamassa residual. Pedir a margem de segurança usual de 5% a 10% evita junta fria, que ocorre quando o concreto novo não pode ser assentado antes do lote anterior começar a travar.',
    'guides.concreteCaption': 'Subleito preparado com base de brita antes da concretagem da laje',
    'guides.concreteAlt': 'Dois trabalhadores com coletes de alta visibilidade apontando para pranchas de construção sobre uma mesa',
    'guides.concreteCaptionAlt': 'Base de brita espalhada ao longo de uma vala de fundação escorada',
    'guides.masonryBadge': 'Guia de alvenaria 02',
    'guides.masonryTitle': 'Medição de paredes de tijolo: geometria de assentamento e margens de argamassa',
    'guides.masonryIntro':
      'Estimar tijolos aparentes modulares exige considerar a espessura da junta de argamassa (nominalmente 3/8 de polegada ou 10 mm). Tijolos modulares padrão dos EUA medem 7-5/8" × 2-1/4" × 3-5/8". Somando as juntas de leito e cabeça, a pegada nominal efetiva passa a ser 8" × 2-2/3".',
    'guides.masonryBody1':
      'Isso resulta no clássico fator de estimativa em alvenaria de aproximadamente <strong>6,75 a 7,0 tijolos modulares por metro quadrado</strong> de superfície de parede de uma fiada. A cimento-alvenaria Type N é o padrão para revestimentos externos, pelo seu equilíbrio entre resistência de aderência à flexão e trabalhabilidade.',
    'guides.masonryAlt': 'Tijolos assentados em espiga com juntas de argamassa visíveis',
    'guides.paintBadge': 'Guia de revestimentos 03',
    'guides.paintTitle': 'Rendimentos de tinta arquitetônica e medições com várias demãos',
    'guides.paintIntro':
      'Tintas látex interiores arquitetônicas de qualidade rendem tipicamente entre 350 e 400 pés quadrados por galão sobre gesso acartonado já preparado. Deduzir as aberturas de janelas e portas garante uma compra precisa:',
    'guides.paintBullet1': 'Portas internas padrão deduzem aproximadamente 21 sq ft (2,0 m²).',
    'guides.paintBullet2': 'Janelas residenciais padrão deduzem aproximadamente 15 sq ft (1,4 m²).',
    'guides.paintBullet3': 'Superfícies sem primer ou texturizadas consomem de 20% a 30% mais tinta na primeira demão.',
    'guides.paintAlt': 'Pintor aplicando uma demão de tinta azul numa parede interna',

    'about.eyebrow': 'Sobre a plataforma',
    'about.title': 'Sobre a MixTally',
    'about.body':
      'A MixTally é uma plataforma aberta de tecnologia para construção que oferece estimativa de quantidades de materiais baseada em fórmulas, combinada com visualização espacial 3D interativa em tempo real.',
    'about.imageAlt': 'Trabalhador de obra anotando observações numa prancheta sobre pranchas de construção',
    'about.problemTitle': 'O problema que resolvemos',
    'about.problemBody1':
      'As calculadoras tradicionais de materiais de construção mostram ao usuário formulários numéricos planos. Ao digitar dimensões com unidades mistas — como uma laje de concreto medida em pés para comprimento e largura, mas em polegadas para espessura — erros de digitação acontecem com frequência. Um ponto decimal no lugar errado ou uma unidade trocada gera um resultado errado por um fator de 12.',
    'about.problemBody2':
      'Na construção real, erros de pedido causam disruptões imediatas do projeto: pedir pouco concreto leva a taxas de emergência de entrega fracionada ou juntas frias fracas, enquanto pedir demais resulta em orçamento desperdiçado e descarte difícil de sobras de argamassa.',
    'about.why3dTitle': 'Por que a modelagem espacial 3D interativa importa',
    'about.why3dBody':
      'Ao conectar os campos numéricos diretamente a um modelo 3D paramétrico WebGL, a MixTally oferece retorno visual imediato. Se o usuário digita sem querer uma laje de 4 polegadas como 4,0 pés, a laje se transforma fisicamente num bloco cúbico no viewport, capturando o erro de entrada antes que qualquer pedido de material seja feito.',
    'about.methodTitle': 'Como os cálculos são gerados',
    'about.method1Label': '1. GEOMETRIA PURA',
    'about.method1Title': 'Equações dimensionais',
    'about.method1Body':
      'Matemática volumétrica padrão ($L \\times W \\times H$) convertida com precisão entre os sistemas Imperial ($ft^3 \\to yd^3$) e Métrico ($m^3$).',
    'about.method2Label': '2. MARGENS CLARAS',
    'about.method2Title': 'Desperdício configurável',
    'about.method2Body':
      'Percentuais transparentes e ajustáveis pelo usuário para assentamento do subleito, flexão de fôrmas, cortes de alvenaria e perdas na rampa.',
    'about.method3Label': '3. EMBALAGEM REAL',
    'about.method3Title': 'Medições comerciais',
    'about.method3Body':
      'Volumes brutos se traduzem em unidades comerciais reais: betoneiras (~9 yd³), sacos de 80 lb / 60 lb, paletes e latas de 5 galões.',
    'about.audienceTitle': 'Para quem a plataforma foi criada',
    'about.audience1Title': 'Construtoras gerais e empreiteiros',
    'about.audience1Body': 'Medições rápidas de materiais, conferência de orçamentos de subcontratados e planejamento da logística de entrega.',
    'about.audience2Title': 'Arquitetos e orçamentistas',
    'about.audience2Body': 'Verificação volumétrica preliminar, conferência de assentamento em alvenaria e cronogramas de revestimento arquitetônico.',
    'about.audience3Title': 'Profissionais das ofícios',
    'about.audience3Body': 'Pedreiros, concretadeiros e pintores que precisam de detalhamentos exatos de unidades e contagem de sacos.',
    'about.audience4Title': 'Aut construtores e faz-tudo',
    'about.audience4Body': 'Orientação clara de compra que evita idas repetidas à loja de materiais e excesso de material em paletes.',
    'about.scopeTitle': 'Escopo e limitações da plataforma',
    'about.scopeBodyLead':
      'A MixTally fornece estimativas matemáticas para orçamento e compras. Não fornecemos engenharia estrutural licenciada, cálculos de cargas nem projetos carimbados para registro. Consulte um engenheiro civil ou arquiteto licenciado para decisões de segurança estrutural. Leia nosso ',
    'about.constructionDisclaimer': 'aviso de responsabilidade completo',

    'contact.eyebrow': 'Suporte técnico e contatos',
