    'brick.faqQ1': 'Quantos tijolos preciso para uma parede?',
    'brick.faqA1':
      'Informe o comprimento e a altura da parede, escolha um predefinição de tijolo (que define o tamanho do tijolo e a espessura da junta de argamassa) e depois selecione o número de fiadas e a margem de desperdício. A calculadora multiplica a área da face da parede pela área efetiva do tijolo por unidade para obter a quantidade base e acrescenta a margem de desperdício para a estimativa de planejamento.',
    'brick.faqQ2': 'Quantos tijolos são necessários por metro quadrado?',
    'brick.faqA2':
      'Com o tijolo modular padrão (7 5/8 in por 2 1/4 in) assentado em junta de argamassa de 3/8 in, a calculadora usa aproximadamente 6,86 tijolos por pé quadrado de parede de fiada simples. No sistema métrico, o padrão é um tijolo de 194 mm por 57 mm com junta de 10 mm.',
    'brick.faqQ3': 'Como calculo os tijolos de uma parede?',
    'brick.faqA3':
      'Calcule a área da face da parede, determine a área efetiva da face do tijolo incluindo a junta de argamassa, divida a área da parede pela área efetiva do tijolo para obter a quantidade base, multiplique pelo número de fiadas e acrescente a margem de desperdício.',
    'brick.faqQ4': 'Quanta argamassa preciso para a alvenaria?',
    'brick.faqA4':
      'A calculadora usa um pressuposto de planejamento de aproximadamente 130 tijolos modulares por saco de 80 lb de argamassa tipo N e informa a quantidade de sacos além do volume aproximado de mistura seca. A necessidade real de argamassa varia conforme as dimensões do tijolo, a espessura da junta, a construção da parede, a execução e o rendimento do produto.',
    'brick.faqQ5': 'Quanto desperdício devo acrescentar ao pedir tijolos?',
    'brick.faqA5':
      'O desperdício depende do tamanho da parede, do arranjo das fiadas, dos cortes e das quebras. A calculadora oferece predefinições de 5%, 8%, 10% e 15% para você escolher a margem que melhor se adapta ao projeto, e mostra os tijolos de desperdício somados à quantidade base.',
    'brick.faqQ6': 'Qual é a diferença entre paredes de fiada simples e fiada dupla?',
    'brick.faqA6':
      'Uma fiada simples é uma camada (folha) de tijolo, enquanto a fiada dupla são duas camadas. A calculadora multiplica a quantidade base de tijolos pelo número de fiadas selecionado, de modo que uma parede de fiada dupla com a mesma área de face precisa de aproximadamente o dobro de tijolos.',
    'brick.faqQ7': 'Quais tamanhos de tijolo esta calculadora suporta?',
    'brick.faqA7':
      'Três predefinições de tijolo: Modular, Rainha e Rei. Cada predefinição carrega um comprimento e uma altura de tijolo correspondentes e a espessura padrão da junta de argamassa, e o botão mostra as dimensões utilizadas. Comprimento e altura da parede são informados diretamente, em unidades métricas ou imperiais.',
    'brick.faqQ8': 'Posso calcular os tijolos usando medidas no sistema métrico?',
    'brick.faqA8':
      'Sim. Alterne o controle de unidades para Métrico (m / mm) para informar comprimento e altura em metros. As predefinições de tijolo e a junta de argamassa passam a usar dimensões em milímetros, como um tijolo modular de 194 mm por 57 mm com junta de 10 mm, e a área da parede é informada em metros quadrados.',
