    'home.faqEyebrow': 'Base de connaissances de terrain',
    'home.faqTitle': 'Principes pratiques de métré de construction',
    'home.faqBody':
      'Questions fréquentes sur le tassement du fond de fouille, les facteurs de rebut, les tolérances de mortier et les déductions d’ouvertures.',
    'home.faq1Question': 'Pourquoi ajouter une marge de commande pour les dalles en béton ?',
    'home.faq1Answer':
      'Les fonds de fouille excavés sont rarement parfaitement de niveau. De légers creux de 1/2 pouce sur une terrasse de 20×20 ft augmentent la consommation de béton de près de 0,6 yard cube. Le coffrage en bois fléchit aussi légèrement vers l’extérieur sous la pression hydrostatique du béton frais. Une marge de commande de 5 % à 10 % évite les joints de reprise causés par des coulées d’urgence incomplètes.',
    'home.faq2Question': 'Combien de briques modulaires faut-il par pied carré de mur ?',
    'home.faq2Answer':
      'Les briques de parement modulaires standard (7-5/8" × 2-1/4" × 3-5/8") avec un joint de lit et de tête standard de 3/8" donnent une face d’appareillage effective de 8" × 2-2/3". Cela équivaut mathématiquement à environ 6,75 à 7,0 briques par pied carré de mur à une seule feuille.',
    'home.faq3Question': 'Quand faut-il déduire les ouvertures lors d’un métré de peinture ?',
    'home.faq3Answer':
      'Les portes intérieures standard mesurent généralement ~21 pi² (2,0 m²) et les fenêtres résidentielles standard occupent ~15 pi² (1,4 m²). Déduire les principales ouvertures évite un surachat important de peinture sur les projets multi-pièces.',
    'home.faq4Question': 'Comment comparer le rendement des sacs aux camions de béton livrés ?',
    'home.faq4Answer':
      'Un yard cube contient 27 pieds cubes. Un sac standard de prémélange de 80 lb rend environ 0,60 pied cube, soit environ 45 sacs de béton de 80 lb (ou 60 sacs de 60 lb) pour former un yard cube. Pour les coulées de plus de 2 yards cubes, les camions de béton prêt à l’emploi livrés sont généralement plus économiques.',

