    'common.faqTitle': 'Questions fréquentes',

    'concrete.faqQ1': 'Combien de sacs de béton de 80 lb équivalent à un yard cube ?',
    'concrete.faqA1':
      'Un sac de 80 livres rend environ 0,60 pied cube. Comme un yard cube contient 27 pieds cubes, il faut mathématiquement environ 45 sacs de béton de 80 lb (ou 60 sacs de 60 lb) par yard cube selon cette hypothèse de planification.',
    'concrete.faqQ2': 'Quelle épaisseur doit avoir une dalle en béton ?',
    'concrete.faqA2':
      'Les allées, promenades et terrasses exigent généralement 4 pouces (10 cm). Les accès de véhicules, les dalles de garage et les semelles de stockage lourd nécessitent un minimum de 5 à 6 pouces (13 à 15 cm) avec armature en barres d’acier ou treillis soudé.',
    'concrete.faqQ3': 'Quel est le poids d’un yard cube de béton ?',
    'concrete.faqA3':
      'Le béton standard de poids normal pèse environ 4 050 livres (environ 2 tonnes ou 1 840 kg) par yard cube lorsqu’il est humide.',

