    'brick.faqQ1': 'Combien de briques me faut-il pour un mur ?',
    'brick.faqA1':
      'Saisissez la longueur et la hauteur du mur, choisissez un préréglage de brique (qui fixe le format de la brique et l’épaisseur du joint de mortier), puis sélectionnez le nombre de feuilles et la marge de rebut. Le calculateur multiplie la surface de la face du mur par la surface effective de la brique par unité pour obtenir la quantité de base, puis ajoute votre marge de rebut pour l’estimation de planification.',
    'brick.faqQ2': 'Combien de briques faut-il par pied carré ?',
    'brick.faqA2':
      'Avec la brique modulaire par défaut (7 5/8 in sur 2 1/4 in) posée dans un joint de mortier de 3/8 in, le calculateur utilise environ 6,86 briques par pied carré de mur à une seule feuille. En unités métriques, la valeur par défaut est une brique de 194 mm sur 57 mm avec un joint de 10 mm.',
    'brick.faqQ3': 'Comment calculer les briques d’un mur ?',
    'brick.faqA3':
      'Calculez la surface de la face du mur, déterminez la surface effective de la brique incluant le joint de mortier, divisez la surface du mur par la surface effective de la brique pour obtenir la quantité de base, multipliez par le nombre de feuilles, puis ajoutez une marge de rebut.',
    'brick.faqQ4': 'Combien de mortier faut-il pour un travail de maçonnerie ?',
    'brick.faqA4':
      'Le calculateur utilise une hypothèse de planification d’environ 130 briques modulaires par sac de 80 lb de mortier de type N et indique le nombre de sacs ainsi que le volume approximatif de mélange sec. Le besoin réel en mortier varie selon les dimensions de la brique, l’épaisseur du joint, la construction du mur, la main-d’œuvre et le rendement du produit.',
    'brick.faqQ5': 'Combien de rebut dois-je ajouter lors de la commande de briques ?',
    'brick.faqA5':
      'Le rebut dépend de la taille du mur, du motif d’appareillage, des coupes et des casses. Le calculateur propose des préréglages de 5 %, 8 %, 10 % et 15 % afin de choisir une marge adaptée à votre projet, et affiche les briques de rebut ajoutées à la quantité de base.',
    'brick.faqQ6': 'Quelle est la différence entre les murs à feuille simple et à feuille double ?',
    'brick.faqA6':
      'Une feuille simple est une couche de brique, tandis qu’une feuille double en compte deux. Le calculateur multiplie la quantité de base de briques par le nombre de feuilles sélectionné : un mur à feuille double de même surface de face nécessite donc environ le double de briques.',
    'brick.faqQ7': 'Quels formats de brique ce calculateur prend-il en charge ?',
    'brick.faqA7':
      'Trois préréglages de brique : Modular, Queen et King. Chaque préréglage charge une longueur, une hauteur et une épaisseur de joint de mortier par défaut correspondantes, et le bouton du préréglage affiche les dimensions utilisées. La longueur et la hauteur du mur se saisissent directement, en unités métriques ou impériales.',
    'brick.faqQ8': 'Puis-je calculer les briques avec des dimensions métriques ?',
    'brick.faqA8':
      'Oui. Passez le sélecteur d’unités en Métrique (m / mm) pour saisir la longueur et la hauteur du mur en mètres. Les préréglages de brique et le joint de mortier utilisent alors des dimensions en millimètres, comme une brique modulaire de 194 mm sur 57 mm avec un joint de 10 mm, et la surface du mur est exprimée en mètres carrés.',
    // ── Blog ───────────────────────────────────────────────────────────
    'blog.eyebrow': 'Calculs de construction',
    'blog.title': 'Blog de construction',
    'blog.intro':
      'Guides de calcul résolus pour les entreprises et les deviseurs : formules, conversions d’unités, passage d’un système d’unités à l’autre et conseils de commande — chaque exemple vérifié avec les calculateurs MixTally.',
    'blog.filterNav': 'Filtrer les articles par catégorie',
