    'home.workflowTitle': 'Sehen Sie die Berechnung, nicht nur die Zahl.',
    'home.workflowBody':
      'MixTally verknüpft physische Baustellenmaße direkt mit parametrischer 3D-Geometrie und verifizierten mathematischen Formeln für klare Planungsschätzungen.',
    'home.step1Label': '01. ABMESSUNGEN',
