    'guides.eyebrow': 'Baureferenz & Leitfäden',
    'guides.title': 'Praxis-Leitfäden und Prinzipien der Materialmengenermittlung',
    'guides.body':
      'Ausführliche technische Leitfäden zu volumetrischen Berechnungsformeln, nominalen Ausschussfaktoren, Verbandsgeometrie und handelsüblichen Bestellpraktiken.',
    'guides.launchCalculator': 'Rechner starten',
    'guides.concreteBadge': 'Beton-Leitfaden 01',
    'guides.concreteTitle':
      'So berechnen Sie das Volumen einer Betondecke und Mischer-Bestellungen',
    'guides.concreteIntro':
      'Gussbeton wird in <strong>Kubikyards</strong> (US-amerikanisches Maßsystem) oder <strong>Kubikmetern</strong> (metrischen Systemen) gemessen und gekauft. Da Maße auf der Baustelle üblicherweise als Länge und Breite in Fuß, aber die Plattendicke in Zoll erfasst werden, ist die korrekte Einheitenumrechnung unverzichtbar:',
    'guides.concreteSubhead': 'Warum Fundationssenkungen eine Bestellzulage erfordern',
    'guides.concreteBody':
      'Der Erdboden ist selten laserflächig. Fundationen senken sich, Schalungen weichen unter dem hohen hydrostatischen Druck des frischen Zements nach außen aus, und Pumpleitungen behalten Restschlamm. Eine übliche Sicherheitsmarge von 5 % bis 10 % verhindert Kaltfugen — sie entstehen, wenn frischer Beton nicht vor dem Abbinden der vorherigen Charge eingebracht werden kann.',
    'guides.concreteCaption': 'Vorbereitete Fundation mit Schotterunterbau vor dem Plattenguss',
    'guides.concreteAlt': 'Zwei Arbeiter in Warnwesten zeigen auf Baupläne auf einem Tisch',
    'guides.concreteCaptionAlt': 'Schotterunterbau in einem abgestützten Fundamentgraben',
    'guides.masonryBadge': 'Mauerwerk-Leitfaden 02',
    'guides.masonryTitle': 'Ziegelwand-Ermittlung: Verbandsgeometrie und Mörtelzulagen',
    'guides.masonryIntro':
      'Die Schätzung von Modulsteinen erfordert die Berücksichtigung der Mörtelfugendicke (nominell 3/8 Zoll beziehungsweise 10 mm). Standard-US-Modulsteine messen 7-5/8" × 2-1/4" × 3-5/8". Mit Lager- und Kopffuge wird der effektive Nennfußabdruck zu 8" × 2-2/3".',
    'guides.masonryBody1':
      'Das ergibt den klassischen Mauerwerksfaktor von etwa <strong>6,75 bis 7,0 Modulsteinen pro Quadratfuß</strong> einreihiger Wandfläche. Zementmörtel Typ N ist bei Außenverblendschalen üblich, da er eine gute Balance aus Biegeverbundfestigkeit und Verarbeitbarkeit bietet.',
    'guides.masonryAlt': 'Steine in Läuferbindung mit sichtbaren Mörtelfugen',
    'guides.paintBadge': 'Beschichtungs-Leitfaden 03',
    'guides.paintTitle': 'Deckungsgrade von Architekturfarbe und Mehrschichtermittlung',
    'guides.paintIntro':
      'Hochwertige latexbasierte Innenfarben decken üblicherweise 350 bis 400 Quadratfuß pro Gallone auf vorgrundiertem Trockenbau. Der Abzug von Fenster- und Tüöffnungen sorgt für einen präzisen Einkauf:',
    'guides.paintBullet1': 'Standard-Innentüren werden mit etwa 21 qft (2,0 m²) abgezogen.',
    'guides.paintBullet2': 'Standard-Wohnungsfenster werden mit etwa 15 qft (1,4 m²) abgezogen.',
    'guides.paintBullet3':
      'Ungedierte oder strukturierte Oberflächen verbrauchen beim ersten Anstrich 20 % bis 30 % mehr Farbe.',
    'guides.paintAlt': 'Ein Maler rollt einen blauen Anstrich auf eine Innenwand',

    'about.eyebrow': 'Über die Plattform',
    'about.title': 'Über MixTally',
    'about.body':
      'MixTally ist eine offene Bautechnologie-Plattform, die formelbasierte Materialmengenschätzung mit interaktiver 3D-Raumvisualisierung in Echtzeit verbindet.',
    'about.imageAlt': 'Baustellenarbeiter notiert auf einem Klemmbrett über Bauplänen',
    'about.problemTitle': 'Das Problem, das wir lösen',
    'about.problemBody1':
      'Traditionelle Baustoffrechner bieten flache numerische Webformulare. Bei der Eingabe mehrerer Einheiten — etwa eine Betondecke, deren Länge und Breite in Fuß, aber deren Dicke in Zoll gemessen wird — passieren Fehler häufig. Ein falsch gesetztes Dezimalzeichen oder eine verwechselte Einheit liefert ein um den Faktor 12 falsches Ergebnis.',
    'about.problemBody2':
      'Im realen Bau führen Bestellfehler zu unmittelbaren Projektstörungen: Unterbestellungen von Beton führen zu Notliefergebühren oder schwachen Kaltfugen, Überbestellungen zu verschwendetem Budget und der schwierigen Entsorgung von Betonrückständen.',
    'about.why3dTitle': 'Warum interaktive 3D-Raummodellierung wichtig ist',
    'about.why3dBody':
      'Durch die direkte Kopplung der numerischen Eingabefelder an ein parametrisches WebGL-3D-Modell liefert MixTally sofortiges visuelles Feedback. Gibt ein Benutzer eine 4-Zoll-Platte versehentlich als 4,0 Fuß ein, verwandelt sich die Platte physisch in einen monolithischen Würfel im Viewport — der Eingabefehler wird erkannt, bevor Material bestellt wird.',
    'about.methodTitle': 'Wie Berechnungen erzeugt werden',
    'about.method1Label': '1. REINE GEOMETRIE',
    'about.method1Title': 'Dimensionsgleichungen',
    'about.method1Body':
      'Standard volumetrische Mathematik ($L \\times W \\times H$), genau umgerechnet zwischen Imperial ($ft^3 \\to yd^3$) und Metrisch ($m^3$).',
    'about.method2Label': '2. KLARE ZULAGEN',
    'about.method2Title': 'Konfigurierbarer Ausschuss',
    'about.method2Body':
      'Transparente, vom Nutzer anpassbare Prozente berücksichtigen Fundationssenkungen, Schalungsverformung, Mauerwerkszuschnitte und Rinnenverluste.',
    'about.method3Label': '3. ECHTE VERPACKUNG',
    'about.method3Title': 'Handelsübliche Mengenermittlung',
    'about.method3Body':
      'Rohvolumen werden in echte Handelsverpackungen übersetzt: Mischer-LKWs (~9 yd³), Säcke zu 80 lb / 60 lb, Paletten und 5-Gal-Eimer.',
    'about.audienceTitle': 'Für wen die Plattform gedacht ist',
    'about.audience1Title': 'Generalunternehmer & Bauherren',
    'about.audience1Body':
      'Schnelle Materialmengenermittlung, Prüfung von Subunternehmerangeboten und Planung der Lieferlogistik.',
    'about.audience2Title': 'Architekten & Kalkulatoren',
    'about.audience2Body':
      'Vorläufige volumetrische Prüfung, Kontrolle des Mauerwerksverbands und architekturbezogene Beschichtungspläne.',
    'about.audience3Title': 'Handwerksberufe',
    'about.audience3Body':
      'Maurer, Betonformer und Maler, die exakte Einheitenaufteilungen und Sackzahlen benötigen.',
    'about.audience4Title': 'Selbstbauer & Heimwerker',
    'about.audience4Body':
      'Klare Einkaufsleitlinien, die wiederholte Baumarktfahrten und Überbestände auf Paletten vermeiden.',
    'about.scopeTitle': 'Plattformumfang & Einschränkungen',
    'about.scopeBodyLead':
      'MixTally liefert mathematische Schätzungen für Budgetierung und Einkauf. Wir stellen weder eine zugelassene Tragwerksplanung, Lastberechnungen noch gestempelte Genehmigungspläne bereit. Konsultieren Sie einen zugelassenen Bauingenieur oder Architekten für Entscheidungen zur strukturellen Sicherheit. Lesen Sie unseren vollständigen ',
    'about.constructionDisclaimer': 'Bau-Haftungsausschluss',

    'contact.eyebrow': 'Technischer Support & Anfragen',
    'contact.title': 'MixTally kontaktieren',
    'contact.body':
      'Fragen zu Rechnerformeln, Fehlerberichte, Funktionswünsche oder technische Partnerschaften.',
    'contact.directTitle': 'Direkter Kontakt',
    'contact.directBody':
      'Wir beantworten Anfragen zu Berechnungsmethoden, Einheitenrundung und Plattformentwicklungen.',
    'contact.primaryEmail': 'Primäre Engineering-E-Mail',
    'contact.directNote': 'Direkte Kommunikation · Keine Systeme Dritter für Ticketverwaltung',
    'contact.submittedTitle': 'E-Mail-Programm gestartet',
    'contact.submittedBodyLead': 'Ihr E-Mail-Programm wurde geöffnet, adressiert an ',
    'contact.submittedBodyTail': '. Sie können uns jederzeit auch direkt schreiben.',
    'contact.sendAnother': 'Weitere Nachricht senden',
    'contact.formTitle': 'Nachricht senden',
    'contact.subjectLabel': 'Thema / Betreff',
