    'brick.faqQ1': 'Wie viele Steine brauche ich für eine Wand?',
    'brick.faqA1':
      'Geben Sie Wandlänge und Wandhöhe ein, wählen Sie eine Steinvorlage (die Steinformat und Mörtelfugendicke festlegt), und legen Sie anschließend die Anzahl der Reihen und die Ausschusszulage fest. Der Rechner multipliziert die Wandverbandsfläche mit der effektiven Steinfläche pro Einheit, um die Grundmenge zu erhalten, und fügt Ihre Ausschusszulage für die Planungsschätzung hinzu.',
    'brick.faqQ2': 'Wie viele Steine braucht man pro Quadratfuß?',
    'brick.faqA2':
      'Bei der Standard-Modulplatte (7 5/8 in × 2 1/4 in) in einer 3/8-in-Mörtelfuge verwendet der Rechner etwa 6,86 Steine pro Quadratfuß einreihiger Wand. In metrischen Einheiten ist der Standard ein Stein von 194 mm × 57 mm mit einer Fuge von 10 mm.',
    'brick.faqQ3': 'Wie berechne ich Steine für eine Wand?',
    'brick.faqA3':
      'Berechnen Sie die Wandverbandsfläche, bestimmen Sie die effektive Steinfläche einschließlich Mörtelfuge, teilen Sie die Wandfläche durch die effektive Steinfläche, um die Grundmenge zu erhalten, multiplizieren Sie mit der Anzahl der Reihen und fügen Sie eine Ausschusszulage hinzu.',
    'brick.faqQ4': 'Wie viel Mörtel brauche ich für Mauerwerk?',
    'brick.faqA4':
      'Der Rechner verwendet eine Planungsannahme von etwa 130 Modulsteinen pro 80-lb-Sack Mörtel Typ N und gibt die Sackanzahl sowie das ungefähre Trockenmischungsvolumen aus. Der tatsächliche Mörtelbedarf hängt von Steinformat, Fugendicke, Wandkonstruktion, Ausführung und Produktausbeute ab.',
    'brick.faqQ5': 'Wie viel Ausschuss sollte ich bei der Steinbestellung hinzufügen?',
    'brick.faqA5':
      'Der Ausschuss hängt von der Wandgröße, dem Verband, den Zuschnitten und Brüchen ab. Der Rechner bietet Vorlagen von 5 %, 8 %, 10 % und 15 %, damit Sie eine zu Ihrem Projekt passende Marge wählen können, und zeigt die zusätzlichen Ausschusssteine zur Grundmenge an.',
    'brick.faqQ6': 'Was ist der Unterschied zwischen einreihigen und zweireihigen Wänden?',
    'brick.faqA6':
      'Eine einreihige Wand ist ein Steinblatt dick, eine zweireihige zwei Blätter. Der Rechner multipliziert die Grundmenge mit der gewählten Anzahl der Reihen — eine zweireihige Wand derselben Verbandsfläche benötigt daher etwa doppelt so viele Steine.',
    'brick.faqQ7': 'Welche Steinformate unterstützt dieser Rechner?',
    'brick.faqA7':
      'Drei Steinvorlagen: Modular, Queen und King. Jede Vorlage lädt eine passende Steinlänge, Steinhöhe und standardmäßige Mörtelfugendicke, und die Schaltfläche zeigt die verwendeten Maße. Wandlänge und Wandhöhe werden direkt in metrischen oder imperialen Einheiten eingegeben.',
    'brick.faqQ8': 'Kann ich Steine mit metrischen Abmessungen berechnen?',
    'brick.faqA8':
      'Ja. Stellen Sie die Einheitensteuerung auf Metrisch (m / mm) um, um Wandlänge und -höhe in Metern einzugeben. Steinvorlagen und Mörtelfuge verwenden dann Millimetermaße, etwa einen 194-mm-×-57-mm-Modulstein mit 10-mm-Fuge, und die Wandfläche wird in Quadratmetern angegeben.',
